import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportGeneratorServlet extends HttpServlet {
    private static final String TEMPLATE_DIR = "/opt/reports/templates/";
    private static final Map<String, String> ALLOWED_REPORTS = new HashMap<>();

    static {
        ALLOWED_REPORTS.put("quarterly", "quarterly_summary.tpl");
        ALLOWED_REPORTS.put("annual", "annual_overview.tpl");
        ALLOWED_REPORTS.put("audit", "audit_log.tpl");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String customTitle = req.getParameter("title");
        String dateRange = req.getParameter("range");
        String outputFormat = req.getParameter("format");

        if (reportType == null || !ALLOWED_REPORTS.containsKey(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Load template
        String templatePath = TEMPLATE_DIR + ALLOWED_REPORTS.get(reportType);
        String template = loadTemplate(templatePath);

        if (template == null) {
            resp.sendError(500, "Template not found");
            return;
        }

        // Build substitution map from user inputs
        Map<String, String> values = new HashMap<>();
        values.put("title", customTitle != null ? customTitle : "Report");
        values.put("date_range", dateRange != null ? dateRange : "last 30 days");
        values.put("generated_by", req.getRemoteUser() != null ? req.getRemoteUser() : "anonymous");
        values.put("format", outputFormat != null ? outputFormat : "pdf");

        // Perform template substitution using Apache Commons Text
        StringSubstitutor substitutor = new StringSubstitutor(values);
        substitutor.setEnableSubstitutionInVariables(true);
        String result = substitutor.replace(template);

        // Generate report via external tool
        String outputFile = "/tmp/report_" + UUID.randomUUID() + "." + 
                           (outputFormat != null ? outputFormat : "pdf");
        ProcessBuilder pb = new ProcessBuilder(
            "/usr/local/bin/report-render",
            "--input", "-",
            "--output", outputFile,
            "--format", outputFormat != null ? outputFormat : "pdf"
        );
        pb.redirectErrorStream(true);
        Process proc = pb.start();

        // Write rendered template to process stdin
        OutputStream procIn = proc.getOutputStream();
        procIn.write(result.getBytes("UTF-8"));
        procIn.close();

        int exitCode = 0;
        try { exitCode = proc.waitFor(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }

        if (exitCode != 0) {
            BufferedReader errReader = new BufferedReader(new InputStreamReader(proc.getInputStream()));
            String errLine = errReader.readLine();
            resp.sendError(500, "Render failed");
            return;
        }

        // Stream output file back
        File output = new File(outputFile);
        if (output.exists()) {
            resp.setContentType("application/octet-stream");
            resp.setHeader("Content-Disposition", "attachment; filename=report." + 
                          (outputFormat != null ? outputFormat : "pdf"));
            try (FileInputStream fis = new FileInputStream(output)) {
                byte[] buf = new byte[4096];
                int len;
                while ((len = fis.read(buf)) != -1) {
                    resp.getOutputStream().write(buf, 0, len);
                }
            }
            output.delete();
        } else {
            resp.sendError(500, "Output not generated");
        }
    }

    private String loadTemplate(String path) {
        try {
            return new String(java.nio.file.Files.readAllBytes(
                java.nio.file.Paths.get(path)), "UTF-8");
        } catch (IOException e) {
            return null;
        }
    }
}
